            Http3 = (value.Http3 ? 1u : 0u),
        };
    internal static NetworkProfileSettings ReadNetworkProfileSettings(NativeNetworkProfileSettings value) =>
        new(ReadAllowedHttpProtocols(value.Protocols),
            value.ReuseConnections != 0,
            value.TlsVersions,
            value.CompatibilityCiphers != 0,
            value.HybridKeyExchange != 0,
            value.Grease,
            value.RandomizeExtensions != 0,
            value.EchGrease != 0,
            value.EncryptedClientHello != 0,
            value.CertificateCompression != 0,
            value.Http2Alps != 0,
            value.Http3Alps != 0,
            value.TrustAnchorIds != 0,
