            TlsVersions = value.TlsVersions,
            CompatibilityCiphers = (value.CompatibilityCiphers ? 1u : 0u),
            HybridKeyExchange = (value.HybridKeyExchange ? 1u : 0u),
            Grease = value.Grease,
            RandomizeExtensions = (value.RandomizeExtensions ? 1u : 0u),
            EchGrease = (value.EchGrease ? 1u : 0u),
            EncryptedClientHello = (value.EncryptedClientHello ? 1u : 0u),
            CertificateCompression = (value.CertificateCompression ? 1u : 0u),
            Http2Alps = (value.Http2Alps ? 1u : 0u),
            Http3Alps = (value.Http3Alps ? 1u : 0u),
            TrustAnchorIds = (value.TrustAnchorIds ? 1u : 0u),
            PkiMetadataFile = (value.PkiMetadataFile is null ? default : new NativeOptionalText { HasValue = 1, Value = arena.Text(value.PkiMetadataFile) }),
